function nestedCrates(crates) {
  const sorted = crates.map(([w, h]) => [w, h]).sort((a, b) => a[0] - b[0]);
  const chain = sorted.map(() => 1);
  let best = 1;
  for (let i = 0; i < sorted.length; i++) {
    for (let j = 0; j < i; j++)
      if (sorted[j][0] < sorted[i][0] && sorted[j][1] < sorted[i][1]) chain[i] = Math.max(chain[i], chain[j] + 1);
    best = Math.max(best, chain[i]);
  }
  return best;
}

